import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './RequestStatusDashboard.css';

// Define the structure of a request object from the backend
interface Request {
    RequestID: number;
    PatientName: string;
    Urgency: 'Emergency' | 'Urgent' | 'Scheduled';
    Status: string;
    CreatedAt: string;
}

const API_URL = 'http://localhost:3001';
const WS_URL = 'ws://localhost:3001';

const RequestStatusDashboard = () => {
    const [requests, setRequests] = useState<Request[]>([]);
    const [error, setError] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    const fetchRequests = async () => {
        // Don't set loading to true on auto-refresh
        // setIsLoading(true); 
        setError(null);
        try {
            const response = await axios.get(`${API_URL}/requests`);
            setRequests(response.data);
        } catch (err) {
            setError('Failed to fetch requests. Is the backend server running?');
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        // Fetch initial data
        fetchRequests();

        // Establish WebSocket connection
        const ws = new WebSocket(WS_URL);

        ws.onopen = () => {
            console.log('WebSocket connected');
        };

        ws.onmessage = (event) => {
            const message = JSON.parse(event.data);
            if (message.type === 'new_update') {
                console.log('Update received, fetching new data...');
                fetchRequests();
            }
        };

        ws.onclose = () => {
            console.log('WebSocket disconnected');
        };

        // Cleanup on component unmount
        return () => {
            ws.close();
        };
    }, []); // Empty dependency array ensures this runs only once on mount

    if (isLoading) {
        return <div>Loading requests...</div>;
    }

    if (error) {
        return <div className="alert error">{error}</div>;
    }

    return (
        <div className="dashboard-container">
            <h2>Your Active Requests</h2>
            {requests.length === 0 ? (
                <p>No active requests found.</p>
            ) : (
                <table className="requests-table">
                    <thead>
                        <tr>
                            <th>Request ID</th>
                            <th>Patient</th>
                            <th>Urgency</th>
                            <th>Status</th>
                            <th>Date</th>
                        </tr>
                    </thead>
                    <tbody>
                        {requests.map((req) => (
                            <tr key={req.RequestID}>
                                <td>{req.RequestID}</td>
                                <td>{req.PatientName}</td>
                                <td>
                                    <span className={`urgency-tag ${req.Urgency.toLowerCase()}`}>
                                        {req.Urgency}
                                    </span>
                                </td>
                                <td>
                                    <span className={`status-tag status-${req.Status.toLowerCase()}`}>
                                        {req.Status.replace(/_/g, ' ')}
                                    </span>
                                </td>
                                <td>{new Date(req.CreatedAt).toLocaleString()}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}
        </div>
    );
};

export default RequestStatusDashboard;
